def _reject_nonfinite_json(value: Any, *, path: Path) -> None:
    pending: list[Any] = [value]
    while pending:
        current = pending.pop()
        if type(current) is dict:
            pending.extend(current.values())
        elif type(current) is list:
            pending.extend(current)
        elif type(current) is float and not math.isfinite(current):
            raise ResearchError(
                "LIGHT_HANDOFF_INVALID",
                "JSON must not contain NaN or Infinity",
                {"path": str(path)},
            )


def _reject_oversized_json_integers(text: str, *, path: Path) -> None:
    limit = sys.get_int_max_str_digits()
    if limit <= 0:
        return
    run = 0
    in_string = False
    escaped = False
    for char in text:
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
            run = 0
            continue
        if char == '"':
            in_string = True
            run = 0
            continue
        if char.isdigit():
            run += 1
            if run > limit:
                raise ResearchError(
                    "LIGHT_HANDOFF_INVALID",
                    "JSON integer exceeds the supported digit limit",
                    {"path": str(path), "digits": run},
                )
            continue
        run = 0


